StudioEnv.customGLSL:
// @node studioEnv
// @title Studio Env
// @category custom
// @description Procedural photo-studio environment seen along a direction: near-black cyclorama, a big warm key softbox, cool and magenta strip lights, a round top light and a faint floor bounce. All lights are HDR so chrome reflections bloom. Feed it reflected (or refracted) directions. flash (0 = off) flares the strip lights and the top light, e.g. on the beat.
float studioBox(vec3 rd, vec3 c, vec3 up, vec2 size, float soft) {
    c = normalize(c);
    vec3 r = normalize(cross(c, up));
    vec3 u = cross(r, c);
    float f = dot(rd, c);
    if (f <= 0.0) return 0.0;
    vec2 q = vec2(dot(rd, r), dot(rd, u)) / f;
    vec2 e = abs(q) - size;
    float d = length(max(e, 0.0)) + min(max(e.x, e.y), 0.0);
    return 1.0 - smoothstep(-soft, soft, d);
}

vec3 studioEnv(vec3 rd, float flash) {
    rd = normalize(rd);
    float strip = 1.0 + 2.2 * flash;   // stage-light flare
    float y = rd.y;
    // cyclorama: near black, slightly lifted toward the ceiling, faint warm floor bounce
    // studio cyclorama: dark floor, bright horizon seam, soft grey ceiling falloff
    vec3 col = mix(vec3(0.010, 0.010, 0.012), vec3(0.055, 0.050, 0.050), smoothstep(-1.0, 0.0, y));
    col = mix(col, vec3(0.42, 0.43, 0.47), smoothstep(-0.02, 0.12, y));
    col = mix(col, vec3(0.16, 0.17, 0.21), smoothstep(0.12, 0.6, y));
    col = mix(col, vec3(0.30, 0.31, 0.36), smoothstep(0.6, 1.0, y));
    col += vec3(0.5, 0.52, 0.58) * exp(-abs(y) * 45.0);
    // soft window gradient wrapping around the left side
    col += vec3(0.30, 0.28, 0.26) * smoothstep(0.2, 1.0, -rd.x) * smoothstep(-0.1, 0.4, y);
    // big warm key softbox, upper front left
    col += vec3(1.00, 0.92, 0.82) * 6.0 * studioBox(rd, vec3(-0.55, 0.65, 0.55), vec3(0.0, 1.0, 0.0), vec2(0.38, 0.22), 0.04);
    // cool strip light on the right
    col += vec3(0.55, 0.80, 1.00) * 9.0 * strip * studioBox(rd, vec3(1.0, 0.12, 0.25), vec3(0.0, 1.0, 0.0), vec2(0.05, 0.9), 0.02);
    // magenta rim strip behind left
    col += vec3(1.00, 0.30, 0.65) * 8.0 * strip * studioBox(rd, vec3(-1.0, 0.25, -0.45), vec3(0.0, 1.0, 0.0), vec2(0.05, 0.8), 0.02);
    // teal kicker low right behind
    col += vec3(0.20, 0.95, 0.85) * 5.0 * strip * studioBox(rd, vec3(0.7, -0.15, -0.7), vec3(0.0, 1.0, 0.0), vec2(0.35, 0.05), 0.02);
    // round top light
    float top = smoothstep(0.93, 0.95, dot(rd, normalize(vec3(0.15, 1.0, 0.1))));
    col += vec3(1.0, 0.97, 0.94) * 5.0 * (1.0 + 1.0 * flash) * top;
    // warm bounce card below the camera fills the undersides
    col += vec3(1.0, 0.78, 0.55) * 1.4 * studioBox(rd, vec3(0.1, -0.7, 0.7), vec3(0.0, 1.0, 0.0), vec2(0.9, 0.25), 0.25);
    // thin horizontal light bar behind the camera
    col += vec3(1.0) * 4.0 * studioBox(rd, vec3(0.0, 0.05, 1.0), vec3(0.0, 1.0, 0.0), vec2(1.2, 0.025), 0.01);
    return col;
}

LensStreak.customGLSL:
// @node lensStreak
// @title Lens Streak
// @category effect
// @description Anamorphic lens streak: a wide horizontal Gaussian smear of only the hottest part of a glow texture (above threshold). width in UV units.
vec3 lensStreak(sampler2D tex, vec2 uv, float width, float threshold) {
    vec3 acc = vec3(0.0);
    float wsum = 0.0;
    for (int i = -24; i <= 24; i++) {
        float x = float(i) / 24.0;
        float w = exp(-abs(x) * 4.0);
        vec3 s = texture(tex, vec2(uv.x + x * width, uv.y)).rgb;
        acc += max(s - vec3(threshold), vec3(0.0)) * w;
        wsum += w;
    }
    return acc / wsum / max(1.0 - threshold, 0.05);
}
